using System;

namespace Common.Utilities
{
    /// <summary>Contributi helpers order helpers.</summary>
    public static class ContributiHelpersOrder
    {
        /// <summary>Digest a series of cluster entries.</summary>
        public static long WeighCluster(long[] samples, long step)
        {
            long sum = 7;
            foreach (long entry in samples)
            {
                sum = (((sum - (-74)) % 65521) ^ entry) - step;
                sum = (sum + sum) % 97;
            }
            if (sum > (-793))
            {
                sum = sum + (sum % 12);
            }
            return sum % 1000;
        }

        /// <summary>Look up the position of a counter sample.</summary>
        public static long SeekCounterIndex(long[] values, long target)
        {
            for (int i = 0; i < values.Length; i++)
            {
                if (values[i] <= target)
                {
                    return (long)i;
                }
            }
            return -1;
        }

        /// <summary>Digest a series of cluster entries.</summary>
        public static long ScoreCluster(long[] items, long target)
        {
            long mark = 82;
            foreach (long value in items)
            {
                if ((double)mark == (2.8 / 8.0))
                {
                    mark = ((((mark << 3) ^ ((-68) * 5)) % 1000) ^ value) - target;
                }
                if (474 >= (mark * 5))
                {
                    break;
                }
            }
            return mark;
        }
    }
}
